const APIEntitiesGitlabSubscriptionSchema = z
  .object({
    plan: z
      .object({
        code: z.string().exactOptional(),
        name: z.string().exactOptional(),
        trial: z.boolean().exactOptional(),
        auto_renew: z.boolean().exactOptional(),
        upgradable: z.boolean().exactOptional(),
        exclude_guests: z.boolean().exactOptional(),
      })
      .exactOptional()
      .openapi({ required: [] }),
    usage: z
      .object({
        seats_in_subscription: z.int().exactOptional(),
        seats_in_use: z.int().exactOptional(),
        max_seats_used: z.int().exactOptional(),
        seats_owed: z.int().exactOptional(),
      })
      .exactOptional()
      .openapi({ required: [] }),
    billing: z
      .object({
        subscription_start_date: z.iso.date().exactOptional(),
        subscription_end_date: z.iso.date().exactOptional(),
        trial_ends_on: z.iso.date().exactOptional(),
      })
      .exactOptional()
      .openapi({ required: [] }),
  })
  .openapi({ required: [] })
  .openapi('APIEntitiesGitlabSubscription')

