const APIEntitiesGeoNodeSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({ type: 'integer', format: 'int64' }),
    name: z.string().exactOptional(),
    url: z.string().exactOptional(),
    internal_url: z.string().exactOptional(),
    primary: z.boolean().exactOptional(),
    enabled: z.boolean().exactOptional(),
    current: z.boolean().exactOptional(),
    files_max_capacity: z.int().exactOptional(),
    repos_max_capacity: z.int().exactOptional(),
    verification_max_capacity: z.int().exactOptional(),
    container_repositories_max_capacity: z.int().exactOptional(),
    selective_sync_type: z.string().exactOptional(),
    selective_sync_shards: z.array(z.any()).exactOptional(),
    selective_sync_namespace_ids: z.array(z.any()).exactOptional(),
    selective_sync_organization_ids: z.array(z.any()).exactOptional(),
    minimum_reverification_interval: z.int().exactOptional(),
    checksum_mismatch_report_threshold: z.int().exactOptional(),
    checksum_mismatch_self_heal_cooldown_minutes: z.int().exactOptional(),
    sync_object_storage: z.boolean().exactOptional(),
    clone_protocol: z.string().exactOptional(),
    web_edit_url: z.string().exactOptional(),
    web_geo_replication_details_url: z.string().exactOptional(),
    _links: z
      .object({
        self: z.string().exactOptional(),
        status: z.string().exactOptional(),
        repair: z.string().exactOptional(),
      })
      .exactOptional()
      .openapi({ required: [] }),
  })
  .openapi({ required: [] })
  .openapi('APIEntitiesGeoNode')

