const PostApiV4GeoFailuresRequestSchema = z
  .object({
    geo_node_id: z
      .int()
      .nullable()
      .openapi({ description: 'The Geo node ID of the reporting secondary' }),
    failures: z
      .array(
        z
          .object({
            error_type: z
              .string()
              .nullable()
              .openapi({
                description: 'The type of verification error being reported',
                example: 'checksum_mismatch',
              }),
            replicable_name: z
              .string()
              .nullable()
              .openapi({
                description: 'The replicable name of a replicator instance',
                example: 'upload',
              }),
            replicable_id: z.int().nullable().openapi({ description: 'The model record ID' }),
            verification_retry_count: z
              .int()
              .nullable()
              .openapi({ description: 'The number of consecutive verification failures' }),
            context: z
              .object({})
              .nullable()
              .exactOptional()
              .openapi({ description: 'Additional error-type-specific data' }),
          })
          .openapi({
            required: [
              'error_type',
              'replicable_name',
              'replicable_id',
              'verification_retry_count',
            ],
          }),
      )
      .nullable()
      .openapi({ description: 'Persistent verification failures reported by the secondary' }),
  })
  .openapi({ required: ['geo_node_id', 'failures'] })
  .openapi('PostApiV4GeoFailuresRequest')

