export const getApiV4ProjectsIdVulnerabilityFindingsRoute = createRoute({
  method: 'get',
  path: '/api/v4/projects/{id}/vulnerability_findings',
  tags: ['Vulnerabilities'],
  summary: 'List all project vulnerability findings',
  description:
    'Lists all vulnerability findings for a specified project. Responses are paginated and return 20 results by default.',
  operationId: 'getApiV4ProjectsIdVulnerabilityFindings',
  request: {
    params: z.object({
      id: ((schema) =>
        z.union([
          z.preprocess(
            (val) =>
              typeof val === 'string' &&
              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                ? Number(val)
                : val,
            schema,
          ),
          schema,
        ]))(z.xor([z.string(), z.int()])).openapi({
        param: {
          name: 'id',
          required: true,
          description: 'ID or URL-encoded path of the project.',
          schema: { oneOf: [{ type: 'string' }, { type: 'integer' }] },
          in: 'path',
        },
      }),
    }),
    query: z.object({
      report_type: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(
            z.enum([
              'sast',
              'dependency_scanning',
              'container_scanning',
              'dast',
              'secret_detection',
              'coverage_fuzzing',
              'api_fuzzing',
              'cluster_image_scanning',
              'container_scanning_for_registry',
              'sarif',
              'generic',
            ]),
          ),
        )
        .default([
          'sast',
          'dependency_scanning',
          'container_scanning',
          'dast',
          'secret_detection',
          'coverage_fuzzing',
          'api_fuzzing',
          'cluster_image_scanning',
          'container_scanning_for_registry',
          'sarif',
          'generic',
        ])
        .exactOptional()
        .openapi({
          param: {
            name: 'report_type',
            required: false,
            description:
              'Return vulnerability findings belonging to the specified report type, such as `sast`, `dast`, `dependency_scanning`, or `container_scanning`.',
            schema: {
              type: 'array',
              items: {
                type: 'string',
                enum: [
                  'sast',
                  'dependency_scanning',
                  'container_scanning',
                  'dast',
                  'secret_detection',
                  'coverage_fuzzing',
                  'api_fuzzing',
                  'cluster_image_scanning',
                  'container_scanning_for_registry',
                  'sarif',
                  'generic',
                ],
              },
              default: [
                'sast',
                'dependency_scanning',
                'container_scanning',
                'dast',
                'secret_detection',
                'coverage_fuzzing',
                'api_fuzzing',
                'cluster_image_scanning',
                'container_scanning_for_registry',
                'sarif',
                'generic',
              ],
            },
            in: 'query',
            style: 'form',
            explode: false,
          },
        }),
      scope: z
        .enum(['all', 'dismissed'])
        .default('dismissed')
        .exactOptional()
        .openapi({
          param: {
            name: 'scope',
            required: false,
            description: 'Return vulnerability findings for the given scope.',
            schema: { type: 'string', enum: ['all', 'dismissed'], default: 'dismissed' },
            in: 'query',
          },
        }),
      severity: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.enum(['info', 'unknown', 'low', 'medium', 'high', 'critical'])),
        )
        .default(['info', 'unknown', 'low', 'medium', 'high', 'critical'])
        .exactOptional()
        .openapi({
          param: {
            name: 'severity',
            required: false,
            description:
              'Return vulnerability findings belonging to the specified severity level: `info`, `unknown`, `low`, `medium`, `high`, or `critical`.',
            schema: {
              type: 'array',
              items: {
                type: 'string',
                enum: ['info', 'unknown', 'low', 'medium', 'high', 'critical'],
              },
              default: ['info', 'unknown', 'low', 'medium', 'high', 'critical'],
            },
            in: 'query',
            style: 'form',
            explode: false,
          },
        }),
      pipeline_id: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'pipeline_id',
            required: false,
            description: 'Filter vulnerability findings by pipeline.',
            schema: { type: 'string', nullable: true },
            in: 'query',
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            required: false,
            description: 'Page number of results to retrieve.',
            schema: { type: 'integer', default: 1 },
            in: 'query',
            example: 1,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            required: false,
            description: 'Number of items to list per page.',
            schema: { type: 'integer', default: 20 },
            in: 'query',
            example: 20,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: { 'application/json': { schema: z.array(VulnerabilitiesFindingEntitySchema) } },
    },
    400: { description: 'Bad Request' },
    404: { description: 'Not Found' },
  },
})

