export const putApiV4ElasticsearchIndexedNamespacesRolloutRoute = createRoute({
  method: 'put',
  path: '/api/v4/elasticsearch_indexed_namespaces/rollout',
  tags: ['Advanced search rollout'],
  summary: 'Rollout namespaces to be indexed up to n%',
  description:
    'This feature was introduced in GitLab 12.7.\n\n**DEPRECATED**: This endpoint is deprecated and for GitLab.com use only.\n\nThis will only ever increase the number of indexed namespaces. Providing a value lower than the current rolled out percentage will have no effect.\n\nThis percentage is never persisted but is used to calculate the number of new namespaces to rollout.\n\nIf the same percentage is applied again at a later time, due to possible new namespaces being created during the period, some of them will also be indexed. Therefore you may expect that setting this to 10%, then waiting a month and setting to 10% again will trigger new namespaces to be added (i.e. 10% of the number of newly created namespaces in the last month within the given plan).\n',
  operationId: 'putApiV4ElasticsearchIndexedNamespacesRollout',
  request: {
    body: {
      content: {
        'application/json': { schema: PutApiV4ElasticsearchIndexedNamespacesRolloutRequestSchema },
      },
      required: true,
    },
  },
  responses: { 200: { description: 'OK' }, 400: { description: 'Bad Request' } },
})

