export const getApiV4AdminDataManagementModelNameRoute = createRoute({
  method: 'get',
  path: '/api/v4/admin/data_management/{model_name}',
  tags: ['Data management'],
  summary: 'Retrieve model information',
  description:
    'Retrieves information about a data model in an instance. Only available to administrators.',
  operationId: 'getApiV4AdminDataManagementModelName',
  request: {
    params: z.object({
      model_name: z
        .string()
        .min(1)
        .openapi({
          param: {
            name: 'model_name',
            required: true,
            description:
              'See https://docs.gitlab.com/administration/admin_area/#data-management for the list of allowed values',
            schema: { type: 'string', minLength: 1 },
            in: 'path',
            example: 'uploads',
          },
        }),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            required: false,
            description: 'Page number of results to retrieve.',
            schema: { type: 'integer', default: 1 },
            in: 'query',
            example: 1,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            required: false,
            description: 'Number of items to list per page.',
            schema: { type: 'integer', default: 20 },
            in: 'query',
            example: 20,
          },
        }),
      identifiers: z
        .xor([
          z.preprocess(
            (val) => (val === 'null' ? null : val),
            z
              .array(
                z.preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                ),
              )
              .nullable(),
          ),
          z.array(z.string()).nullable(),
        ])
        .exactOptional()
        .openapi({
          param: {
            name: 'identifiers',
            required: false,
            description:
              'Filter results with an array of unique identifiers of the requested model, which can be integers or base64 encoded strings.',
            schema: {
              oneOf: [
                { type: 'array', items: { type: 'integer' }, nullable: true },
                { type: 'array', items: { type: 'string' }, nullable: true },
              ],
            },
            in: 'query',
          },
        }),
      checksum_state: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        z.enum(['pending', 'started', 'succeeded', 'failed', 'disabled']).nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'checksum_state',
            required: false,
            description: 'Filter by checksum status.',
            schema: {
              type: 'string',
              enum: ['pending', 'started', 'succeeded', 'failed', 'disabled'],
              nullable: true,
            },
            in: 'query',
          },
        }),
      cursor: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'cursor',
            required: false,
            description: 'Cursor for obtaining the next set of records.',
            schema: { type: 'string', nullable: true },
            in: 'query',
          },
        }),
      sort: z
        .enum(['asc', 'desc'])
        .default('asc')
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            required: false,
            description: 'Sort results in ascending or descending order.',
            schema: { type: 'string', enum: ['asc', 'desc'], default: 'asc' },
            in: 'query',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: { 'application/json': { schema: z.array(APIEntitiesAdminModelSchema) } },
    },
    400: { description: '400 Bad request' },
    401: { description: '401 Unauthorized' },
    403: { description: '403 Forbidden' },
    404: { description: '404 Model Not Found' },
  },
})

