export const getApiV4TopicsRoute = createRoute({
  method: 'get',
  path: '/api/v4/topics',
  tags: ['Project topics'],
  summary: 'List all topics',
  description: 'Lists all project topics sorted by the number of associated projects.',
  operationId: 'getApiV4Topics',
  request: {
    query: z.object({
      search: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'search',
            required: false,
            description: 'Search topics against their `name`.',
            schema: { type: 'string', nullable: true },
            in: 'query',
            example: 'search',
          },
        }),
      without_projects: z
        .preprocess((val) => (val === 'null' ? null : val), z.stringbool().nullable())
        .exactOptional()
        .openapi({
          param: {
            name: 'without_projects',
            required: false,
            description: 'If `true`, returns only topics that have no assigned projects.',
            schema: { type: 'boolean', nullable: true },
            in: 'query',
          },
        }),
      organization_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'organization_id',
            required: false,
            description: 'Filter topics by organization ID.',
            schema: { type: 'integer' },
            in: 'query',
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            required: false,
            description: 'Page number of results to retrieve.',
            schema: { type: 'integer', default: 1 },
            in: 'query',
            example: 1,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(20)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            required: false,
            description: 'Number of items to list per page.',
            schema: { type: 'integer', default: 20 },
            in: 'query',
            example: 20,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: { 'application/json': { schema: APIEntitiesProjectsTopicSchema } },
    },
    400: { description: 'Bad Request' },
  },
})

export const postApiV4TopicsRoute = createRoute({
  method: 'post',
  path: '/api/v4/topics',
  tags: ['Project topics'],
  summary: 'Create a project topic',
  description: 'Creates a project topic. Administrators only.',
  operationId: 'postApiV4Topics',
  request: {
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              name: z.string().nullable().openapi({ description: 'Slug (name)' }),
              title: z.string().nullable().openapi({ description: 'Title' }),
              description: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({ description: 'Description' }),
              avatar: ((schema) =>
                z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
                z.file().nullable(),
              )
                .exactOptional()
                .openapi({
                  type: ['string', 'null'],
                  format: 'binary',
                  description: 'Avatar image for topic',
                }),
              organization_id: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({ description: 'The organization id for the topic' }),
            })
            .openapi({ required: ['name', 'title'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Created',
      content: { 'application/json': { schema: APIEntitiesProjectsTopicSchema } },
    },
    400: { description: 'Bad Request' },
  },
})

